A = []
def mx_app(nm, reg, lat, lon, txt, grapes, prod, styles=("red", "white"), dom="red", cat="Region", created=None, sub=None, match=None):
    kw = {"styles": list(styles), "dominant_style": dom, "grapes": grapes}
    if prod: kw["producers"] = prod
    if created: kw["created"] = created
    if sub: kw["subregion"] = sub
    kw["match"] = match or [nm]
    d = app("mx", nm, cat, reg, txt, **kw)
    d["lat"], d["lon"] = lat, lon
    return d
A.append(mx_app("Valle de Guadalupe", BC, 32.09, -116.57,
 "Mexico's most famous wine valley, about 20 km northeast of Ensenada along Highway 3, the Ruta del Vino. Dominicans founded the mission of Nuestra Señora de Guadalupe del Norte here in 1834; Russian Molokan families farmed the valley from 1905 (their museum survives in Francisco Zarco); L.A. Cetto and Domecq industrialised it from the 1970s; and Monte Xanic (1987), Château Camou, Adobe Guadalupe, Casa de Piedra and dozens of boutique wineries turned it into a food-and-wine destination, from 6 wineries in 1999 to about 150 in 2023.\n\nThe climate is Mediterranean, with hot days moderated by Pacific air drawn through the canyon from El Sauzal, and the soils are sandy decomposed granite. Reds dominate: Cabernet Sauvignon, Tempranillo, Nebbiolo, Merlot, Grenache and blends that combine ripe fruit with a saline, slightly bitter edge. Water is the valley's crisis: vineyards draw on an overexploited aquifer, and salinity is rising.",
 "Cabernet Sauvignon, Tempranillo, Nebbiolo, Merlot, Syrah, Grenache, Zinfandel, Chenin Blanc", ["Monte Xanic", "L.A. Cetto", "Château Camou", "Adobe Guadalupe", "Vena Cava", "Bruma", "Vinícola Torres Alegre", "Las Nubes", "Hacienda La Lomita"], match=["Valle de Guadalupe", "Guadalupe Valley"]))
