A.append(mx_app("Valle de Santo Tomás", BC, 31.56, -116.41, "A valley about 45 km south of Ensenada, site of the Dominican mission of Santo Tomás de Aquino (1791) and the vineyards of Bodegas de Santo Tomás, Baja California's first commercial winery (1888). Cooler, windier and with heavier soils than Guadalupe.", "Cabernet Sauvignon, Tempranillo, Chenin Blanc, Chardonnay", ["Bodegas de Santo Tomás"]))
A.append(mx_app("Valle de San Vicente", BC, 31.33, -116.25, "A broad valley about 90 km south of Ensenada around San Vicente, with a Dominican mission founded in 1780. Warm and dry, it supplies grapes to many Guadalupe wineries and grows Cabernet, Tempranillo and Grenache.", "Cabernet Sauvignon, Tempranillo, Grenache, Merlot", ["Bodegas San Rafael (sourcing)"]))
A.append(mx_app("Valle de Ojos Negros", BC, 31.91, -116.27, "A high inland valley east of Ensenada at about 700 m, cooler at night than the coastal valleys, with snow on the surrounding mountains in winter. Monte Xanic and others grow fresh Sauvignon Blanc and Chardonnay and Pinot Noir here.", "Sauvignon Blanc, Chardonnay, Cabernet Sauvignon, Pinot Noir", ["Monte Xanic (Ojos Negros vineyards)", "Bodegas Henri Lurton"], styles=("white", "red"), dom="white"))
