A.append(mx_app("Zacatecas", CH, 22.57, -102.23, "A high-plateau state (about 2,000 m) that was Mexico's second-largest wine-grape producer in 2025 (26,024 t), mostly around Ojocaliente and Luis Moya, historically supplying brandy distillers. A handful of wineries now bottle Cabernet, Tempranillo and Merlot.", "Cabernet Sauvignon, Tempranillo, Merlot, Ruby Cabernet", []))
