S.append(site("freixenet-mexico", "mx", "Freixenet de México (Finca Sala Vivé)", "house", "Querétaro", 20.7044, -99.8755, "The Catalan cava house Freixenet chose Ezequiel Montes in the 1970s; its traditional-method sparkling wines age in deep underground cellars, and it anchors Querétaro's wine route.", producers=["Freixenet de México"]))
S.append(site("la-redonda", "mx", "Viñedos La Redonda", "estate", "Querétaro", 20.6366, -99.9019, "One of Querétaro's pioneering wineries, founded in the 1970s on the high plateau near Ezequiel Montes at about 1,900 m. Its still and sparkling wines and busy harvest festivals helped turn the Querétaro wine and cheese route into central Mexico's main wine-tourism destination.", producers=["La Redonda"]))
S.append(site("cuna-de-tierra", "mx", "Cuna de Tierra", "estate", "Guanajuato", 21.2090, -100.8499, "A winery near Dolores Hidalgo whose vineyards helped revive wine in Hidalgo's town; its name ('cradle of earth') nods to Dolores as the cradle of Mexican independence.", producers=["Cuna de Tierra"]))
S.append(site("dolores-parroquia", "mx", "Parroquia de Dolores (Miguel Hidalgo)", "historic", "Guanajuato", 21.1575, -100.9342, "From this parish church Father Miguel Hidalgo issued the Grito de Dolores on 16 September 1810. As priest he had taught villagers to cultivate vines, mulberries for silk and pottery, industries the Spanish crown restricted; officials ordered his vines destroyed.", cls="1810", q="approx"))
S.append(site("cerocahui", "mx", "Cerocahui mission", "historic", "Chihuahua", 27.2980, -108.0553, "A Jesuit mission founded in the late 17th century deep in the Copper Canyon where mission-era vines are still tended and a little wine is made, a reminder of the colonial vineyards that once dotted the Sierra Madre.", q="approx"))
